import { useEffect } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom"
import { setTokenCookie, verifyEmail } from "../services/AccountService";
import { paypalCapture } from "../services/PaymentService";
import { toast } from "react-toastify";

export default function PayPalSuccessPage() {
    const nav = useNavigate();
    const { order_token } = useParams();
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const token = queryParams.get("token");
    const payerId = queryParams.get("PayerID");
    useEffect(() => {
        const time = setTimeout(() => {
            const fetch = async () => {
                try {
                    const res = await paypalCapture(order_token, token)
                    if (res?.status == 'success') {
                        toast.success('Update account successffully!');
                    } else {
                        toast.error(res.status +" | Update unsuccessful | Contact Admin")
                    }
                    nav('/')
                } catch (err) {
                    nav('/');
                }
            }
            fetch();
        }, 1500);
        return () => clearTimeout(time);
    })
    return (<>
        <div className="verify-loading">
            <svg height="48px" width="64px">
                <polyline id="back" points="0.157 23.954, 14 23.954, 21.843 48, 43 0, 50 24, 64 24"></polyline>
                <polyline id="front" points="0.157 23.954, 14 23.954, 21.843 48, 43 0, 50 24, 64 24"></polyline>
                <polyline id="front2" points="0.157 23.954, 14 23.954, 21.843 48, 43 0, 50 24, 64 24"></polyline>
            </svg>
        </div>
    </>)
}